#include "lista.h"

void inicializar(TLista *l) {
  l->cantidad = 0;
}

int longitud(TLista l) {
  return l.cantidad;
}

int obtener(TLista l, int pos) {
  return l.elementos[pos];
}

TResultado insertar(TLista *l, int pos, int x) {
  if (l->cantidad == MAX) {
    return LISTA_LLENA;
  }
  if (pos < 0 || pos > l->cantidad) {
    return POSICION_INVALIDA;
  }
  for (int i = l->cantidad; i > pos; i--) {
    l->elementos[i] = l->elementos[i - 1];
  }
  l->elementos[pos] = x;
  l->cantidad = l->cantidad + 1;
  return OK;
}

TResultado eliminar(TLista *l, int pos) {
  if (pos < 0 || pos >= l->cantidad) {
    return POSICION_INVALIDA;
  }
  for (int i = pos; i < l->cantidad - 1; i++) {
    l->elementos[i] = l->elementos[i + 1];
  }
  l->cantidad = l->cantidad - 1;
  return OK;
}

#include <stdio.h>
#include "lista.h"

int main() {
  TLista l;
  int n;
  int x;
  int p;
  int q;
  int a;
  int b;

  inicializar(&l);
  scanf("%d", &n);
  for (int i = 0; i < n; i++) {
    scanf("%d", &x);
    insertar(&l, longitud(l), x);
  }
  scanf("%d", &p);
  scanf("%d", &q);
  a = obtener(l, p);
  b = obtener(l, q);
  eliminar(&l, p);
  insertar(&l, p, b);
  eliminar(&l, q);
  insertar(&l, q, a);
  for (int i = 0; i < longitud(l); i++) {
    printf("%d ", obtener(l, i));
  }
  return 0;
}
